"""Durable read-only workflow scheduling and event triggering.

Jobs may only launch allow-listed Agent V2 workflows.  They never receive a
draft write capability and cannot invoke confirmation or submission paths.
"""

from __future__ import annotations

import json
import re
import threading
from contextlib import suppress
from datetime import UTC, datetime, time, timedelta
from typing import Any
from zoneinfo import ZoneInfo, ZoneInfoNotFoundError

from enterprise_agent.errors import ConflictError, NotFoundError
from enterprise_agent.harness.sanitize import (
    has_secret_material,
    redact_text,
    sanitize,
)
from enterprise_agent.util import (
    canonical_json,
    random_id,
    sha256_json,
    utc_now,
    utc_text,
)

_ACTOR = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:@-]{0,127}$")
_IDENTIFIER = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$")
_EVENT_TYPE = re.compile(r"^[a-z][a-z0-9_.:-]{0,63}$")
_WORKFLOWS = frozenset({"daily_coal_health"})
_SCHEDULE_KINDS = frozenset({"daily", "interval", "event"})
_ZERO_HASH = "0" * 64
_MAX_JOBS_PER_ACTOR = 50
_MAX_JOBS_TOTAL = 1_000
_MAX_EVENT_PAYLOAD_BYTES = 16 * 1024
_EVENT_CLAIM_SECONDS = 120


def _json_details(row: Any) -> dict[str, Any]:
    try:
        value = json.loads(row["details_json"])
    except (json.JSONDecodeError, KeyError, TypeError, ValueError):
        return {}
    return value if isinstance(value, dict) else {}


def _safe_actor(value: Any) -> str:
    if not isinstance(value, str) or _ACTOR.fullmatch(value) is None:
        raise ValueError("actor_id 格式非法")
    return value


def _safe_identifier(value: Any, field: str) -> str:
    if not isinstance(value, str) or _IDENTIFIER.fullmatch(value) is None:
        raise ValueError(f"{field} 格式非法")
    return value


def _safe_text(value: Any, field: str, maximum: int, *, required: bool) -> str:
    if value is None and not required:
        return ""
    if not isinstance(value, str):
        raise ValueError(f"{field} 必须是文本")
    text_value = value.strip()
    if required and not text_value:
        raise ValueError(f"{field} 不能为空")
    if len(text_value) > maximum or any(
        ord(character) < 32 and character not in "\n\t"
        for character in text_value
    ):
        raise ValueError(f"{field} 超出长度限制或包含控制字符")
    if has_secret_material(text_value):
        raise ValueError(f"{field} 不得包含密码、令牌或 API 密钥")
    return redact_text(text_value, maximum=maximum)


def _safe_client_id(value: Any, field: str) -> str | None:
    if value is None:
        return None
    return _safe_identifier(value, field)


def _event_name(value: Any) -> str:
    if not isinstance(value, str) or _EVENT_TYPE.fullmatch(value) is None:
        raise ValueError(
            "event_type 必须是小写字母开头的 1-64 位业务事件名"
        )
    return value


def _schedule(
    schedule_kind: Any,
    raw_schedule: Any,
) -> tuple[str, dict[str, Any]]:
    if schedule_kind not in _SCHEDULE_KINDS:
        raise ValueError("schedule_kind 只能是 daily、interval 或 event")
    if not isinstance(raw_schedule, dict):
        raise ValueError("schedule 必须是对象")
    if schedule_kind == "interval":
        if set(raw_schedule) != {"interval_seconds"}:
            raise ValueError("interval 计划只接受 interval_seconds")
        seconds = raw_schedule.get("interval_seconds")
        if (
            isinstance(seconds, bool)
            or not isinstance(seconds, int)
            or not 300 <= seconds <= 30 * 24 * 60 * 60
        ):
            raise ValueError("interval_seconds 必须在 300 到 2592000 之间")
        return schedule_kind, {"interval_seconds": seconds}
    if schedule_kind == "daily":
        if set(raw_schedule) != {"time", "timezone"}:
            raise ValueError("daily 计划必须且只能包含 time 和 timezone")
        raw_time = raw_schedule.get("time")
        timezone_name = raw_schedule.get("timezone")
        if (
            not isinstance(raw_time, str)
            or re.fullmatch(r"(?:[01]\d|2[0-3]):[0-5]\d", raw_time) is None
        ):
            raise ValueError("daily time 必须是 HH:MM")
        if (
            not isinstance(timezone_name, str)
            or not timezone_name
            or len(timezone_name) > 64
        ):
            raise ValueError("daily timezone 格式非法")
        try:
            ZoneInfo(timezone_name)
        except (ZoneInfoNotFoundError, ValueError) as error:
            raise ValueError("daily timezone 不是可用的 IANA 时区") from error
        return schedule_kind, {
            "time": raw_time,
            "timezone": timezone_name,
        }
    if set(raw_schedule) != {"event_type"}:
        raise ValueError("event 计划只接受 event_type")
    return schedule_kind, {"event_type": _event_name(raw_schedule.get("event_type"))}


def _next_run_at(
    schedule_kind: str,
    schedule: dict[str, Any],
    *,
    after: datetime,
) -> str | None:
    if schedule_kind == "event":
        return None
    if schedule_kind == "interval":
        return utc_text(after.astimezone(UTC) + timedelta(
            seconds=int(schedule["interval_seconds"])
        ))
    zone = ZoneInfo(str(schedule["timezone"]))
    hour, minute = (int(part) for part in str(schedule["time"]).split(":"))
    local_after = after.astimezone(zone)
    candidate = datetime.combine(
        local_after.date(),
        time(hour=hour, minute=minute),
        tzinfo=zone,
    )
    if candidate <= local_after:
        candidate += timedelta(days=1)
    return utc_text(candidate)


class AgentJobScheduler:
    """Persistent scheduler whose only effect is launching read-only flows."""

    version = "agent-job-scheduler-v1"

    def __init__(
        self,
        repository: Any,
        flow_runtime: Any,
        *,
        poll_seconds: float = 5.0,
        auto_start: bool = True,
    ):
        if not 0.25 <= float(poll_seconds) <= 60:
            raise ValueError("poll_seconds 必须在 0.25 到 60 之间")
        self.repository = repository
        self.flow_runtime = flow_runtime
        self.poll_seconds = float(poll_seconds)
        self._lifecycle_lock = threading.RLock()
        self._wake = threading.Event()
        self._closed = threading.Event()
        self._thread: threading.Thread | None = None
        self._recover_next_runs()
        if auto_start:
            self.start()

    def start(self) -> None:
        with self._lifecycle_lock:
            if self._closed.is_set():
                raise RuntimeError("调度器已经关闭")
            if self._thread is not None and self._thread.is_alive():
                return
            self._thread = threading.Thread(
                target=self._loop,
                name="enterprise-agent-v2-scheduler",
                daemon=True,
            )
            self._thread.start()
            self._wake.set()

    def close(self) -> None:
        with self._lifecycle_lock:
            self._closed.set()
            self._wake.set()
        if (
            self._thread is not None
            and self._thread.is_alive()
            and self._thread is not threading.current_thread()
        ):
            self._thread.join(timeout=max(2.0, self.poll_seconds + 1.0))

    def create_job(
        self,
        *,
        actor_id: Any,
        name: Any,
        workflow_name: Any = "daily_coal_health",
        draft_id: Any,
        schedule_kind: Any,
        schedule: Any,
        goal_text: Any = "",
        enabled: Any = True,
        client_request_id: Any = None,
    ) -> dict[str, Any]:
        with self._lifecycle_lock:
            if self._closed.is_set():
                raise RuntimeError("调度器已经关闭")
            return self._create_job(
                actor_id=actor_id,
                name=name,
                workflow_name=workflow_name,
                draft_id=draft_id,
                schedule_kind=schedule_kind,
                schedule=schedule,
                goal_text=goal_text,
                enabled=enabled,
                client_request_id=client_request_id,
            )

    def _create_job(
        self,
        *,
        actor_id: Any,
        name: Any,
        workflow_name: Any = "daily_coal_health",
        draft_id: Any,
        schedule_kind: Any,
        schedule: Any,
        goal_text: Any = "",
        enabled: Any = True,
        client_request_id: Any = None,
    ) -> dict[str, Any]:
        actor = _safe_actor(actor_id)
        job_name = _safe_text(name, "name", 128, required=True)
        workflow = self._workflow(workflow_name)
        draft = self._draft_id(draft_id)
        kind, material = _schedule(schedule_kind, schedule)
        goal = _safe_text(goal_text, "goal_text", 1_000, required=False)
        if not isinstance(enabled, bool):
            raise ValueError("enabled 必须是布尔值")
        client_id = _safe_client_id(client_request_id, "client_request_id")
        request_hash = sha256_json(
            {
                "name": job_name,
                "workflow_name": workflow,
                "draft_id": draft,
                "goal_text": goal,
                "schedule_kind": kind,
                "schedule": material,
                "enabled": enabled,
                "client_request_id": client_id,
            }
        )
        now = utc_now()
        with self.repository._transaction() as db:
            if client_id is not None:
                replay = db.execute(
                    """
                    SELECT * FROM agent_jobs
                    WHERE actor_id = ? AND client_request_id = ?
                    """,
                    (actor, client_id),
                ).fetchone()
                if replay is not None:
                    if not self._verify_row_in_transaction(db, replay)["valid"]:
                        raise ConflictError(
                            "定时任务审计完整性校验失败，拒绝幂等复用"
                        )
                    created_event = db.execute(
                        """
                        SELECT details_json
                        FROM agent_job_events
                        WHERE job_id = ? AND sequence = 1
                          AND event_type = 'job_created'
                        """,
                        (replay["job_id"],),
                    ).fetchone()
                    stored_hash = None
                    if created_event is not None:
                        try:
                            stored_hash = json.loads(
                                created_event["details_json"]
                            ).get("request_sha256")
                        except (json.JSONDecodeError, AttributeError, TypeError):
                            stored_hash = None
                    if stored_hash is None:
                        # Compatibility for jobs created before request hashes
                        # were recorded. Current fields are the best available
                        # evidence; ambiguous reuse is rejected.
                        stored_hash = sha256_json(
                            {
                                "name": str(replay["name"]),
                                "workflow_name": str(
                                    replay["workflow_name"]
                                ),
                                "draft_id": replay["draft_id"],
                                "goal_text": str(replay["goal_text"]),
                                "schedule_kind": str(
                                    replay["schedule_kind"]
                                ),
                                "schedule": json.loads(
                                    replay["schedule_json"]
                                ),
                                "enabled": bool(replay["enabled"]),
                                "client_request_id": replay[
                                    "client_request_id"
                                ],
                            }
                        )
                    if stored_hash != request_hash:
                        raise ConflictError(
                            "client_request_id 已用于不同的定时任务"
                        )
                    return self._row(replay)
            active_rows = db.execute(
                """
                SELECT * FROM agent_jobs WHERE deleted_at IS NULL
                """
            ).fetchall()
            verified_rows = [
                row
                for row in active_rows
                if self._verify_row_in_transaction(db, row)["valid"]
            ]
            actor_count = sum(
                1 for row in verified_rows if str(row["actor_id"]) == actor
            )
            if actor_count >= _MAX_JOBS_PER_ACTOR:
                raise ConflictError("当前账号的定时任务已达到 50 个上限")
            if len(verified_rows) >= _MAX_JOBS_TOTAL:
                raise ConflictError("服务的定时任务已满")
            job_id = random_id("job")
            timestamp = utc_text(now)
            next_run = (
                _next_run_at(kind, material, after=now)
                if enabled
                else None
            )
            db.execute(
                """
                INSERT INTO agent_jobs (
                    job_id, actor_id, client_request_id, name, workflow_name,
                    draft_id, goal_text, schedule_kind, schedule_json,
                    enabled, next_run_at, revision, created_at, updated_at
                ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?)
                """,
                (
                    job_id,
                    actor,
                    client_id,
                    job_name,
                    workflow,
                    draft,
                    goal,
                    kind,
                    canonical_json(material),
                    int(enabled),
                    next_run,
                    timestamp,
                    timestamp,
                ),
            )
            self._append_event(
                db,
                job_id=job_id,
                event_type="job_created",
                actor_id=actor,
                details={
                    "workflow_name": workflow,
                    "schedule_kind": kind,
                    "schedule_sha256": sha256_json(material),
                    "enabled": enabled,
                    "draft_id": draft,
                    "request_sha256": request_hash,
                    "config_sha256": request_hash,
                },
                occurred_at=timestamp,
            )
            row = db.execute(
                "SELECT * FROM agent_jobs WHERE job_id = ?",
                (job_id,),
            ).fetchone()
        self._wake.set()
        return self._row(row)

    def list_jobs(
        self,
        *,
        actor_id: Any,
        limit: int = 20,
        offset: int = 0,
    ) -> tuple[list[dict[str, Any]], int]:
        actor = _safe_actor(actor_id)
        if not 1 <= limit <= 100 or not 0 <= offset <= 1_000_000:
            raise ValueError("分页参数超出范围")
        with self.repository._read() as db:
            db.execute("BEGIN")
            try:
                total = db.execute(
                    """
                    SELECT COUNT(*) AS amount FROM agent_jobs
                    WHERE actor_id = ? AND deleted_at IS NULL
                    """,
                    (actor,),
                ).fetchone()
                rows = db.execute(
                    """
                    SELECT * FROM agent_jobs
                    WHERE actor_id = ? AND deleted_at IS NULL
                    ORDER BY updated_at DESC, job_id
                    LIMIT ? OFFSET ?
                    """,
                    (actor, limit, offset),
                ).fetchall()
                jobs = []
                for row in rows:
                    job = self._row(row)
                    job["integrity"] = self._verify_row_in_transaction(db, row)
                    jobs.append(job)
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        return jobs, int(total["amount"])

    def get_job(self, job_id: Any, *, actor_id: Any) -> dict[str, Any]:
        actor = _safe_actor(actor_id)
        identifier = _safe_identifier(job_id, "job_id")
        with self.repository._read() as db:
            db.execute("BEGIN")
            try:
                row = db.execute(
                    """
                    SELECT * FROM agent_jobs
                    WHERE job_id = ? AND actor_id = ? AND deleted_at IS NULL
                    """,
                    (identifier, actor),
                ).fetchone()
                if row is None:
                    raise NotFoundError("定时任务不存在")
                events = db.execute(
                    """
                    SELECT * FROM agent_job_events
                    WHERE job_id = ? ORDER BY sequence
                    """,
                    (identifier,),
                ).fetchall()
                db.execute("COMMIT")
            except BaseException:
                db.execute("ROLLBACK")
                raise
        job = self._row(row)
        try:
            public_events = [self._event_row(event) for event in events]
            integrity = self._verify_events(row, public_events)
        except (json.JSONDecodeError, TypeError, ValueError):
            public_events = []
            integrity = {
                "valid": False,
                "event_count": len(events),
                "head_hash": str(row["event_head_hash"]),
                "config_bound": False,
                "state_bound": False,
            }
        job["events"] = public_events
        job["integrity"] = integrity
        return job

    def update_job(
        self,
        job_id: Any,
        *,
        actor_id: Any,
        expected_revision: Any,
        patch: Any,
    ) -> dict[str, Any]:
        with self._lifecycle_lock:
            if self._closed.is_set():
                raise RuntimeError("调度器已经关闭")
            return self._update_job(
                job_id,
                actor_id=actor_id,
                expected_revision=expected_revision,
                patch=patch,
            )

    def _update_job(
        self,
        job_id: Any,
        *,
        actor_id: Any,
        expected_revision: Any,
        patch: Any,
    ) -> dict[str, Any]:
        actor = _safe_actor(actor_id)
        identifier = _safe_identifier(job_id, "job_id")
        if (
            isinstance(expected_revision, bool)
            or not isinstance(expected_revision, int)
            or expected_revision < 1
        ):
            raise ValueError("expected_revision 必须是正整数")
        if not isinstance(patch, dict) or not patch:
            raise ValueError("patch 必须是非空对象")
        allowed = {
            "name",
            "draft_id",
            "goal_text",
            "schedule_kind",
            "schedule",
            "enabled",
        }
        unknown = set(patch) - allowed
        if unknown:
            raise ValueError("不支持修改字段：" + ", ".join(sorted(unknown)))
        now = utc_now()
        with self.repository._transaction() as db:
            row = db.execute(
                """
                SELECT * FROM agent_jobs
                WHERE job_id = ? AND actor_id = ? AND deleted_at IS NULL
                """,
                (identifier, actor),
            ).fetchone()
            if row is None:
                raise NotFoundError("定时任务不存在")
            if not self._verify_row_in_transaction(db, row)["valid"]:
                raise ConflictError(
                    "定时任务审计完整性校验失败，拒绝修改"
                )
            if int(row["revision"]) != expected_revision:
                raise ConflictError(
                    f"任务已更新，当前修订号为 {int(row['revision'])}"
                )
            name = (
                _safe_text(patch["name"], "name", 128, required=True)
                if "name" in patch
                else str(row["name"])
            )
            draft = (
                self._draft_id(patch["draft_id"])
                if "draft_id" in patch
                else row["draft_id"]
            )
            goal = (
                _safe_text(
                    patch["goal_text"],
                    "goal_text",
                    1_000,
                    required=False,
                )
                if "goal_text" in patch
                else str(row["goal_text"])
            )
            kind = str(row["schedule_kind"])
            material = json.loads(row["schedule_json"])
            if "schedule_kind" in patch or "schedule" in patch:
                kind, material = _schedule(
                    patch.get("schedule_kind", kind),
                    patch.get("schedule", material),
                )
            enabled = bool(row["enabled"])
            if "enabled" in patch:
                if not isinstance(patch["enabled"], bool):
                    raise ValueError("enabled 必须是布尔值")
                enabled = patch["enabled"]
            next_run = (
                _next_run_at(kind, material, after=now)
                if enabled
                else None
            )
            timestamp = utc_text(now)
            changed = db.execute(
                """
                UPDATE agent_jobs
                SET name = ?, draft_id = ?, goal_text = ?,
                    schedule_kind = ?, schedule_json = ?, enabled = ?,
                    next_run_at = ?, pending_run_at = NULL,
                    revision = revision + 1, updated_at = ?
                WHERE job_id = ? AND actor_id = ? AND revision = ?
                  AND deleted_at IS NULL
                """,
                (
                    name,
                    draft,
                    goal,
                    kind,
                    canonical_json(material),
                    int(enabled),
                    next_run,
                    timestamp,
                    identifier,
                    actor,
                    expected_revision,
                ),
            )
            if changed.rowcount != 1:
                raise ConflictError("任务刚刚被其他请求更新")
            self._append_event(
                db,
                job_id=identifier,
                event_type="job_updated",
                actor_id=actor,
                details={
                    "changed_fields": sorted(patch),
                    "schedule_sha256": sha256_json(material),
                    "enabled": enabled,
                    "config_sha256": self._config_sha256(
                        name=name,
                        workflow_name=str(row["workflow_name"]),
                        draft_id=draft,
                        goal_text=goal,
                        schedule_kind=kind,
                        schedule=material,
                        enabled=enabled,
                        client_request_id=row["client_request_id"],
                    ),
                },
                occurred_at=timestamp,
            )
            updated = db.execute(
                "SELECT * FROM agent_jobs WHERE job_id = ?",
                (identifier,),
            ).fetchone()
        self._wake.set()
        return self._row(updated)

    def delete_job(
        self,
        job_id: Any,
        *,
        actor_id: Any,
        expected_revision: Any = None,
    ) -> dict[str, Any]:
        with self._lifecycle_lock:
            if self._closed.is_set():
                raise RuntimeError("调度器已经关闭")
            return self._delete_job(
                job_id,
                actor_id=actor_id,
                expected_revision=expected_revision,
            )

    def _delete_job(
        self,
        job_id: Any,
        *,
        actor_id: Any,
        expected_revision: Any = None,
    ) -> dict[str, Any]:
        actor = _safe_actor(actor_id)
        identifier = _safe_identifier(job_id, "job_id")
        if expected_revision is not None and (
            isinstance(expected_revision, bool)
            or not isinstance(expected_revision, int)
            or expected_revision < 1
        ):
            raise ValueError("expected_revision 必须是正整数")
        timestamp = utc_text()
        with self.repository._transaction() as db:
            row = db.execute(
                """
                SELECT * FROM agent_jobs
                WHERE job_id = ? AND actor_id = ? AND deleted_at IS NULL
                """,
                (identifier, actor),
            ).fetchone()
            if row is None:
                raise NotFoundError("定时任务不存在")
            if not self._verify_row_in_transaction(db, row)["valid"]:
                raise ConflictError(
                    "定时任务审计完整性校验失败，拒绝删除"
                )
            if (
                expected_revision is not None
                and int(row["revision"]) != expected_revision
            ):
                raise ConflictError(
                    f"任务已更新，当前修订号为 {int(row['revision'])}"
                )
            changed = db.execute(
                """
                UPDATE agent_jobs
                SET enabled = 0, next_run_at = NULL, pending_run_at = NULL,
                    deleted_at = ?,
                    revision = revision + 1, updated_at = ?
                WHERE job_id = ?
                """,
                (timestamp, timestamp, identifier),
            )
            if changed.rowcount != 1:
                raise ConflictError("任务刚刚被其他请求删除或更新")
            self._append_event(
                db,
                job_id=identifier,
                event_type="job_deleted",
                actor_id=actor,
                details={
                    "previous_revision": int(row["revision"]),
                    "config_sha256": self._config_sha256(
                        name=str(row["name"]),
                        workflow_name=str(row["workflow_name"]),
                        draft_id=str(row["draft_id"]),
                        goal_text=str(row["goal_text"]),
                        schedule_kind=str(row["schedule_kind"]),
                        schedule=json.loads(row["schedule_json"]),
                        enabled=False,
                        client_request_id=row["client_request_id"],
                    ),
                },
                occurred_at=timestamp,
            )
            deleted = db.execute(
                "SELECT * FROM agent_jobs WHERE job_id = ?",
                (identifier,),
            ).fetchone()
        self._wake.set()
        result = self._row(deleted)
        result["deleted"] = True
        return result

    def run_now(
        self,
        job_id: Any,
        *,
        actor_id: Any,
        trigger_type: str = "manual",
        trigger_ref: str | None = None,
        client_request_id: Any = None,
    ) -> dict[str, Any]:
        with self._lifecycle_lock:
            if self._closed.is_set():
                raise RuntimeError("调度器已经关闭")
            return self._run_now(
                job_id,
                actor_id=actor_id,
                trigger_type=trigger_type,
                trigger_ref=trigger_ref,
                client_request_id=client_request_id,
            )

    def _run_now(
        self,
        job_id: Any,
        *,
        actor_id: Any,
        trigger_type: str = "manual",
        trigger_ref: str | None = None,
        client_request_id: Any = None,
    ) -> dict[str, Any]:
        actor = _safe_actor(actor_id)
        job = self.get_job(job_id, actor_id=actor)
        if not job["integrity"]["valid"]:
            raise ConflictError(
                "定时任务审计完整性校验失败，拒绝创建智能体任务"
            )
        if trigger_type not in {"manual", "schedule", "event"}:
            raise ValueError("trigger_type 不受支持")
        reference = (
            _safe_identifier(trigger_ref, "trigger_ref")
            if trigger_ref is not None
            else job["job_id"]
        )
        manual_request_id = _safe_client_id(
            client_request_id,
            "client_request_id",
        )
        if trigger_type != "manual" and manual_request_id is not None:
            raise ValueError("只有人工立即运行接受 client_request_id")
        launch_revision = int(job["revision"])
        launch_config_sha256 = self._config_sha256(
            name=job["name"],
            workflow_name=job["workflow_name"],
            draft_id=job["draft_id"],
            goal_text=job["goal_text"],
            schedule_kind=job["schedule_kind"],
            schedule=job["schedule"],
            enabled=job["enabled"],
            client_request_id=job.get("client_request_id"),
        )
        request_material = {
            "job_id": job["job_id"],
            "trigger_type": trigger_type,
            "trigger_ref": reference,
        }
        if trigger_type == "manual" and manual_request_id is None:
            request_material["started_at"] = utc_text()
        elif trigger_type == "manual":
            request_material["client_request_id"] = manual_request_id
        nonce = sha256_json(request_material)[:32]
        client_request_id = f"job:{job['job_id'][-24:]}:{nonce}"
        find_existing = getattr(
            self.flow_runtime.store,
            "find_by_client_request",
            None,
        )
        flow = (
            find_existing(
                actor_id=actor,
                client_request_id=client_request_id,
            )
            if callable(find_existing)
            else None
        )
        existing_request = flow is not None
        if flow is None:
            flow = self.flow_runtime.create(
                actor_id=actor,
                workflow_name=job["workflow_name"],
                draft_id=job["draft_id"],
                goal=job["goal_text"],
                client_request_id=client_request_id,
                trigger_type=trigger_type,
                trigger_ref=reference,
                defer_dispatch=True,
            )
        now = utc_text()
        try:
            with self._lifecycle_lock, self.repository._transaction() as db:
                if self._closed.is_set():
                    raise RuntimeError("调度器已经关闭")
                current = db.execute(
                    """
                    SELECT * FROM agent_jobs
                    WHERE job_id = ? AND actor_id = ? AND deleted_at IS NULL
                    """,
                    (job["job_id"], actor),
                ).fetchone()
                if current is None:
                    raise ConflictError("定时任务在启动期间已删除")
                if not self._verify_row_in_transaction(db, current)["valid"]:
                    raise ConflictError(
                        "定时任务审计完整性校验失败，拒绝记录本次运行"
                    )
                existing = self.flow_runtime.store.get_in_transaction(
                    db,
                    flow["flow_id"],
                )
                if (
                    existing_request
                    and existing.get("status") == "cancelled"
                ):
                    reopened = (
                        self.flow_runtime.store
                        .reopen_abandoned_deferred_in_transaction(
                            db,
                            flow["flow_id"],
                            actor_id=actor,
                        )
                    )
                    if reopened:
                        existing = (
                            self.flow_runtime.store.get_in_transaction(
                                db,
                                flow["flow_id"],
                            )
                        )
                existing_trigger = existing.get("trigger")
                existing_trigger_type = (
                    existing_trigger.get("type")
                    if isinstance(existing_trigger, dict)
                    else existing.get("trigger_type")
                )
                existing_trigger_ref = (
                    existing_trigger.get("ref")
                    if isinstance(existing_trigger, dict)
                    else existing.get("trigger_ref")
                )
                if (
                    existing.get("actor_id") != actor
                    or existing_trigger_type != trigger_type
                    or existing_trigger_ref != reference
                    or not existing.get("integrity", {}).get("valid")
                ):
                    raise ConflictError(
                        "任务关联的幂等智能体流不一致，拒绝重放"
                    )
                already_linked = current["last_flow_id"] == flow["flow_id"]
                if existing.get("dispatch_ready") and not already_linked:
                    linked_events = db.execute(
                        """
                        SELECT details_json FROM agent_job_events
                        WHERE job_id = ? AND event_type = 'job_flow_created'
                        ORDER BY sequence
                        """,
                        (job["job_id"],),
                    ).fetchall()
                    already_linked = any(
                        _json_details(item).get("flow_id")
                        == flow["flow_id"]
                        for item in linked_events
                    )
                if existing.get("dispatch_ready"):
                    if not already_linked:
                        raise ConflictError(
                            "已授权智能体流缺少对应计划审计，拒绝重放"
                        )
                    # The exact event occurrence was already authorized and
                    # audited.  Never append a duplicate job_flow_created.
                else:
                    current_config = self._config_sha256(
                        name=str(current["name"]),
                        workflow_name=str(current["workflow_name"]),
                        draft_id=str(current["draft_id"]),
                        goal_text=str(current["goal_text"]),
                        schedule_kind=str(current["schedule_kind"]),
                        schedule=json.loads(current["schedule_json"]),
                        enabled=bool(current["enabled"]),
                        client_request_id=current["client_request_id"],
                    )
                    if (
                        current_config != launch_config_sha256
                        and not (
                            trigger_type == "manual"
                            and manual_request_id is not None
                            and existing_request
                        )
                    ):
                        raise ConflictError(
                            "定时任务在启动期间已更新；"
                            "本次只读流未挂接到新配置"
                        )
                    current_revision = int(current["revision"])
                    changed = db.execute(
                        """
                        UPDATE agent_jobs
                        SET last_run_at = ?, last_flow_id = ?,
                            last_error = NULL,
                            revision = revision + 1, updated_at = ?
                        WHERE job_id = ? AND revision = ?
                        """,
                        (
                            now,
                            flow["flow_id"],
                            now,
                            job["job_id"],
                            current_revision,
                        ),
                    )
                    if changed.rowcount != 1:
                        raise ConflictError("定时任务刚刚被其他请求更新")
                    self.flow_runtime.authorize_dispatch_in_transaction(
                        db,
                        flow["flow_id"],
                        actor_id=actor,
                    )
                    self._append_event(
                        db,
                        job_id=job["job_id"],
                        event_type="job_flow_created",
                        actor_id=actor,
                        details={
                            "flow_id": flow["flow_id"],
                            "trigger_type": trigger_type,
                            "trigger_ref": reference,
                            "request_job_revision": launch_revision,
                            "commit_job_revision": current_revision,
                            "request_job_config_sha256": (
                                launch_config_sha256
                            ),
                            "commit_job_config_sha256": current_config,
                            "executed_flow_material_sha256": sha256_json(
                                {
                                    "workflow_name": existing.get(
                                        "workflow_name"
                                    ),
                                    "workflow_version": existing.get(
                                        "workflow_version"
                                    ),
                                    "draft_id": existing.get("draft_id"),
                                    "goal": existing.get("goal"),
                                    "trigger": existing.get("trigger"),
                                }
                            ),
                            "stable_request_replay": bool(
                                existing_request
                            ),
                            "execution_configuration_source": (
                                "existing_idempotent_flow"
                                if existing_request
                                else "current_job"
                            ),
                            **(
                                {}
                                if existing_request
                                else {
                                    "launch_revision": launch_revision,
                                    "commit_revision": current_revision,
                                    "launch_config_sha256": (
                                        launch_config_sha256
                                    ),
                                }
                            ),
                        },
                        occurred_at=now,
                    )
        except Exception:
            # Keep the non-dispatchable flow as a durable idempotency record.
            # Exact retries can safely finish the atomic job/audit attachment;
            # parent-aware recovery later expires a true orphan.
            if not (
                trigger_type == "manual" and manual_request_id is not None
            ):
                with suppress(ConflictError, NotFoundError):
                    self.flow_runtime.abandon_deferred(
                        flow["flow_id"],
                        actor_id=actor,
                        reason_code="scheduler_launch_aborted",
                    )
            raise
        with suppress(ConflictError):
            self.flow_runtime.schedule_existing(flow["flow_id"])
        return self.flow_runtime.store.get(flow["flow_id"])

    def emit_event(
        self,
        *,
        actor_id: Any,
        event_type: Any,
        client_event_id: Any,
        draft_id: Any = None,
        payload: Any = None,
    ) -> dict[str, Any]:
        with self._lifecycle_lock:
            if self._closed.is_set():
                raise RuntimeError("调度器已经关闭")
            return self._emit_event(
                actor_id=actor_id,
                event_type=event_type,
                client_event_id=client_event_id,
                draft_id=draft_id,
                payload=payload,
            )

    def _emit_event(
        self,
        *,
        actor_id: Any,
        event_type: Any,
        client_event_id: Any,
        draft_id: Any = None,
        payload: Any = None,
    ) -> dict[str, Any]:
        actor = _safe_actor(actor_id)
        event_name = _event_name(event_type)
        client_id = _safe_identifier(client_event_id, "client_event_id")
        draft = self._draft_id(draft_id) if draft_id is not None else None
        material = {} if payload is None else payload
        if not isinstance(material, dict):
            raise ValueError("payload 必须是对象")
        if has_secret_material(material):
            raise ValueError("payload 不得包含密码、令牌或 API 密钥")
        clean_payload = sanitize(material)
        encoded = canonical_json(clean_payload)
        if len(encoded.encode("utf-8")) > _MAX_EVENT_PAYLOAD_BYTES:
            raise ValueError("payload 超过 16 KiB")
        payload_hash = sha256_json(clean_payload)
        replayed = False
        claim_owner = random_id("event-worker")
        with self.repository._transaction() as db:
            replay = db.execute(
                """
                SELECT * FROM agent_trigger_events
                WHERE actor_id = ? AND client_event_id = ?
                """,
                (actor, client_id),
            ).fetchone()
            if replay is not None:
                verification = self._verify_trigger_row(replay)
                if not verification["valid"]:
                    raise ConflictError(
                        "业务事件记录完整性校验失败，拒绝重放"
                    )
                if (
                    str(replay["event_type"]) != event_name
                    or replay["draft_id"] != draft
                    or str(replay["payload_sha256"]) != payload_hash
                ):
                    raise ConflictError(
                        "client_event_id 已用于不同的业务事件"
                    )
                event_id = str(replay["event_id"])
                progress = verification["progress"]
                progress_revision = int(verification["revision"])
                progress_hash = str(verification["progress_sha256"])
                record_hash = str(verification["record_sha256"])
                replayed = True
                if progress["completed"]:
                    db.execute(
                        """
                        DELETE FROM agent_trigger_claims
                        WHERE event_id = ? AND lease_expires_at <= ?
                        """,
                        (event_id, utc_text()),
                    )
                    return self._trigger_row(replay, replayed=True)
            else:
                event_id = random_id("evt")
                now = utc_text()
                rows = db.execute(
                    """
                    SELECT * FROM agent_jobs
                    WHERE actor_id = ? AND enabled = 1
                      AND deleted_at IS NULL AND schedule_kind = 'event'
                    ORDER BY created_at, job_id
                    """,
                    (actor,),
                ).fetchall()
                matched_job_ids = []
                for row in rows:
                    schedule = json.loads(row["schedule_json"])
                    if schedule.get("event_type") != event_name:
                        continue
                    if (
                        row["draft_id"] is not None
                        and row["draft_id"] != draft
                    ):
                        continue
                    matched_job_ids.append(str(row["job_id"]))
                progress = {
                    "matched_job_ids": matched_job_ids,
                    "succeeded": [],
                    "failed": [],
                    "completed": False,
                }
                matched_jobs_json = canonical_json(matched_job_ids)
                record_hash = self._trigger_record_sha256(
                    event_id=event_id,
                    actor_id=actor,
                    client_event_id=client_id,
                    event_type=event_name,
                    draft_id=draft,
                    payload_sha256=payload_hash,
                    matched_job_ids=matched_job_ids,
                    occurred_at=now,
                )
                progress_revision = 1
                progress_hash = self._trigger_progress_sha256(
                    event_id=event_id,
                    record_sha256=record_hash,
                    revision=progress_revision,
                    progress=progress,
                )
                db.execute(
                    """
                    INSERT INTO agent_trigger_events (
                        event_id, actor_id, client_event_id, event_type,
                        draft_id, payload_json, payload_sha256,
                        matched_jobs_json, triggered_jobs_json, record_sha256,
                        progress_revision, progress_sha256, occurred_at
                    ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        event_id,
                        actor,
                        client_id,
                        event_name,
                        draft,
                        encoded,
                        payload_hash,
                        matched_jobs_json,
                        canonical_json(progress),
                        record_hash,
                        progress_revision,
                        progress_hash,
                        now,
                    ),
                )
            if not self._claim_trigger_in_transaction(
                db,
                event_id=event_id,
                owner_id=claim_owner,
            ):
                stored = db.execute(
                    """
                    SELECT * FROM agent_trigger_events WHERE event_id = ?
                    """,
                    (event_id,),
                ).fetchone()
                return self._trigger_row(stored, replayed=True)
        try:
            succeeded = {
                str(item["job_id"]): dict(item)
                for item in progress["succeeded"]
                if isinstance(item, dict)
                and isinstance(item.get("job_id"), str)
            }
            failures = {
                str(item["job_id"]): dict(item)
                for item in progress["failed"]
                if isinstance(item, dict)
                and isinstance(item.get("job_id"), str)
            }
            for job_id in progress["matched_job_ids"]:
                if job_id in succeeded:
                    continue
                self._renew_trigger_claim(event_id, owner_id=claim_owner)
                try:
                    flow = self.run_now(
                        job_id,
                        actor_id=actor,
                        trigger_type="event",
                        trigger_ref=event_id,
                    )
                    succeeded[job_id] = {
                        "job_id": job_id,
                        "flow_id": flow["flow_id"],
                    }
                    failures.pop(job_id, None)
                except Exception as error:
                    # Keep unrelated event jobs independent.
                    failures[job_id] = {
                        "job_id": job_id,
                        "error": type(error).__name__,
                    }
                progress = {
                    "matched_job_ids": progress["matched_job_ids"],
                    "succeeded": list(succeeded.values()),
                    "failed": list(failures.values()),
                    "completed": False,
                }
                (
                    progress_revision,
                    progress_hash,
                    progress,
                ) = self._persist_trigger_progress(
                    event_id=event_id,
                    record_sha256=record_hash,
                    expected_revision=progress_revision,
                    expected_progress_sha256=progress_hash,
                    progress=progress,
                    claim_owner=claim_owner,
                )
            progress["completed"] = True
            (
                progress_revision,
                progress_hash,
                progress,
            ) = self._persist_trigger_progress(
                event_id=event_id,
                record_sha256=record_hash,
                expected_revision=progress_revision,
                expected_progress_sha256=progress_hash,
                progress=progress,
                claim_owner=claim_owner,
            )
            with self.repository._transaction() as db:
                stored = db.execute(
                    "SELECT * FROM agent_trigger_events WHERE event_id = ?",
                    (event_id,),
                ).fetchone()
            return self._trigger_row(stored, replayed=replayed)
        finally:
            self._release_trigger_claim(event_id, owner_id=claim_owner)

    def list_trigger_events(
        self,
        *,
        actor_id: Any,
        limit: int = 20,
    ) -> list[dict[str, Any]]:
        actor = _safe_actor(actor_id)
        if not 1 <= limit <= 100:
            raise ValueError("limit 必须在 1-100 之间")
        with self.repository._read() as db:
            rows = db.execute(
                """
                SELECT * FROM agent_trigger_events
                WHERE actor_id = ?
                ORDER BY occurred_at DESC, event_id
                LIMIT ?
                """,
                (actor, limit),
            ).fetchall()
        return [self._trigger_row(row, replayed=False) for row in rows]

    def run_due_once(self, *, now: datetime | None = None) -> list[str]:
        if self._closed.is_set():
            return []
        self._resume_incomplete_events()
        if self._closed.is_set():
            return []
        current = (now or utc_now()).astimezone(UTC)
        current_text = utc_text(current)
        with self.repository._read() as db:
            pending = db.execute(
                """
                SELECT * FROM agent_jobs
                WHERE enabled = 1 AND deleted_at IS NULL
                  AND schedule_kind IN ('daily', 'interval')
                  AND pending_run_at IS NOT NULL
                ORDER BY pending_run_at, job_id
                LIMIT 100
                """
            ).fetchall()
            due = db.execute(
                """
                SELECT job_id, actor_id FROM agent_jobs
                WHERE enabled = 1 AND deleted_at IS NULL
                  AND schedule_kind IN ('daily', 'interval')
                  AND pending_run_at IS NULL
                  AND next_run_at IS NOT NULL AND next_run_at <= ?
                ORDER BY next_run_at, job_id
                LIMIT 100
                """,
                (current_text,),
            ).fetchall()
        flows: list[str] = []
        for row in pending:
            claimed = self._row(row)
            claimed["scheduled_for"] = str(row["pending_run_at"])
            try:
                flow = self._launch_claimed(claimed)
                flows.append(str(flow["flow_id"]))
            except Exception as error:
                if self._closed.is_set():
                    break
                self._abandon_failed_occurrence(claimed)
                self._record_job_error(
                    claimed["job_id"],
                    type(error).__name__,
                    scheduled_for=claimed["scheduled_for"],
                )
        for candidate in due:
            claimed = self._claim_due(
                candidate["job_id"],
                actor_id=candidate["actor_id"],
                now=current,
            )
            if claimed is None:
                continue
            try:
                flow = self._launch_claimed(claimed)
                flows.append(str(flow["flow_id"]))
            except Exception as error:  # one broken job must not stop scheduler
                if self._closed.is_set():
                    break
                self._abandon_failed_occurrence(claimed)
                self._record_job_error(
                    claimed["job_id"],
                    type(error).__name__,
                    scheduled_for=claimed["scheduled_for"],
                )
        return flows

    def _resume_incomplete_events(self, *, limit: int = 50) -> list[str]:
        """Resume integrity-valid event checkpoints left by an interrupted host."""

        pending: list[dict[str, Any]] = []
        last_occurred_at = ""
        last_event_id = ""
        batch_size = max(100, limit)
        with self.repository._read() as db:
            while len(pending) < limit:
                rows = db.execute(
                    """
                    SELECT * FROM agent_trigger_events
                    WHERE triggered_jobs_json LIKE '%"completed":false%'
                      AND (
                        occurred_at > ?
                        OR (occurred_at = ? AND event_id > ?)
                      )
                    ORDER BY occurred_at, event_id
                    LIMIT ?
                    """,
                    (
                        last_occurred_at,
                        last_occurred_at,
                        last_event_id,
                        batch_size,
                    ),
                ).fetchall()
                if not rows:
                    break
                for row in rows:
                    verified = self._verify_trigger_row(row)
                    if (
                        verified["valid"]
                        and not verified["progress"]["completed"]
                    ):
                        pending.append(
                            {
                                "event_id": str(row["event_id"]),
                                "actor_id": str(row["actor_id"]),
                                "event_type": str(row["event_type"]),
                                "client_event_id": str(
                                    row["client_event_id"]
                                ),
                                "draft_id": row["draft_id"],
                                "payload": verified["payload"],
                            }
                        )
                        if len(pending) >= limit:
                            break
                last_occurred_at = str(rows[-1]["occurred_at"])
                last_event_id = str(rows[-1]["event_id"])
                if len(rows) < batch_size:
                    break
        completed: list[str] = []
        for event in pending:
            if self._closed.is_set():
                break
            try:
                result = self.emit_event(
                    actor_id=event["actor_id"],
                    event_type=event["event_type"],
                    client_event_id=event["client_event_id"],
                    draft_id=event["draft_id"],
                    payload=event["payload"],
                )
            except Exception:
                continue
            if result["triggered"]["completed"]:
                completed.append(event["event_id"])
        return completed

    def _abandon_failed_occurrence(self, job: dict[str, Any]) -> None:
        """Release quota for a scheduled occurrence that has been closed."""

        scheduled_for = str(job["scheduled_for"])
        request_hash = sha256_json(
            {"job_id": job["job_id"], "scheduled_for": scheduled_for}
        )[:32]
        request_id = (
            f"schedule:{str(job['job_id'])[-20:]}:{request_hash}"
        )
        find_existing = getattr(
            self.flow_runtime.store,
            "find_by_client_request",
            None,
        )
        if not callable(find_existing):
            return
        with suppress(ConflictError, NotFoundError):
            flow = find_existing(
                actor_id=str(job["actor_id"]),
                client_request_id=request_id,
            )
            if flow is not None:
                self.flow_runtime.abandon_deferred(
                    str(flow["flow_id"]),
                    actor_id=str(job["actor_id"]),
                    reason_code="scheduler_launch_aborted",
                )

    def _loop(self) -> None:
        while not self._closed.is_set():
            self._wake.wait(self.poll_seconds)
            self._wake.clear()
            if self._closed.is_set():
                break
            try:
                self.run_due_once()
            except Exception:
                # The next tick retries due jobs. Never expose payloads or
                # exception text from a background thread.
                continue

    def _claim_due(
        self,
        job_id: str,
        *,
        actor_id: str,
        now: datetime,
    ) -> dict[str, Any] | None:
        now_text = utc_text(now)
        with self.repository._transaction() as db:
            row = db.execute(
                """
                SELECT * FROM agent_jobs
                WHERE job_id = ? AND actor_id = ? AND enabled = 1
                  AND deleted_at IS NULL AND pending_run_at IS NULL
                  AND next_run_at IS NOT NULL
                  AND next_run_at <= ?
                """,
                (job_id, actor_id, now_text),
            ).fetchone()
            if row is None:
                return None
            if not self._verify_row_in_transaction(db, row)["valid"]:
                return None
            scheduled_for = str(row["next_run_at"])
            schedule = json.loads(row["schedule_json"])
            next_run = _next_run_at(
                str(row["schedule_kind"]),
                schedule,
                after=now,
            )
            changed = db.execute(
                """
                UPDATE agent_jobs
                SET next_run_at = ?, pending_run_at = ?,
                    last_run_at = ?, last_error = NULL,
                    revision = revision + 1, updated_at = ?
                WHERE job_id = ? AND next_run_at = ?
                """,
                (
                    next_run,
                    scheduled_for,
                    now_text,
                    now_text,
                    job_id,
                    scheduled_for,
                ),
            )
            if changed.rowcount != 1:
                return None
            self._append_event(
                db,
                job_id=job_id,
                event_type="job_due_claimed",
                actor_id="system",
                details={
                    "scheduled_for": scheduled_for,
                    "next_run_at": next_run,
                },
                occurred_at=now_text,
            )
            result = self._row(row)
            result["scheduled_for"] = scheduled_for
        return result

    def _launch_claimed(self, job: dict[str, Any]) -> dict[str, Any]:
        if self._closed.is_set():
            raise RuntimeError("调度器已经关闭")
        scheduled_for = str(job["scheduled_for"])
        verified = self.get_job(
            job["job_id"],
            actor_id=job["actor_id"],
        )
        if not verified["integrity"]["valid"]:
            raise ConflictError(
                "定时任务审计完整性校验失败，拒绝执行该周期"
            )
        if verified["pending_run_at"] != scheduled_for:
            raise ConflictError("定时任务周期已变化，拒绝重复执行")
        job = verified
        job["scheduled_for"] = scheduled_for
        launch_revision = int(job["revision"])
        launch_config_sha256 = self._config_sha256(
            name=job["name"],
            workflow_name=job["workflow_name"],
            draft_id=job["draft_id"],
            goal_text=job["goal_text"],
            schedule_kind=job["schedule_kind"],
            schedule=job["schedule"],
            enabled=job["enabled"],
            client_request_id=job.get("client_request_id"),
        )
        request_hash = sha256_json(
            {"job_id": job["job_id"], "scheduled_for": scheduled_for}
        )[:32]
        flow = self.flow_runtime.create(
            actor_id=job["actor_id"],
            workflow_name=job["workflow_name"],
            draft_id=job["draft_id"],
            goal=job["goal_text"],
            client_request_id=f"schedule:{job['job_id'][-20:]}:{request_hash}",
            trigger_type="schedule",
            trigger_ref=job["job_id"],
            defer_dispatch=True,
        )
        now = utc_text()
        with self._lifecycle_lock, self.repository._transaction() as db:
            if self._closed.is_set():
                raise RuntimeError("调度器已经关闭")
            current = db.execute(
                "SELECT * FROM agent_jobs WHERE job_id = ?",
                (job["job_id"],),
            ).fetchone()
            if current is None:
                raise ConflictError("定时任务在启动期间已删除")
            if not self._verify_row_in_transaction(db, current)["valid"]:
                raise ConflictError(
                    "定时任务审计完整性校验失败，拒绝记录本次运行"
                )
            existing = self.flow_runtime.store.get_in_transaction(
                db,
                flow["flow_id"],
            )
            existing_trigger = existing.get("trigger")
            existing_type = (
                existing_trigger.get("type")
                if isinstance(existing_trigger, dict)
                else existing.get("trigger_type")
            )
            existing_ref = (
                existing_trigger.get("ref")
                if isinstance(existing_trigger, dict)
                else existing.get("trigger_ref")
            )
            if (
                existing.get("actor_id") != job["actor_id"]
                or existing_type != "schedule"
                or existing_ref != job["job_id"]
                or not existing.get("integrity", {}).get("valid")
            ):
                raise ConflictError("定时周期关联的智能体流不一致")
            already_linked = current["last_flow_id"] == flow["flow_id"]
            if existing.get("dispatch_ready") and not already_linked:
                linked_events = db.execute(
                    """
                    SELECT details_json FROM agent_job_events
                    WHERE job_id = ? AND event_type = 'job_flow_created'
                    ORDER BY sequence
                    """,
                    (job["job_id"],),
                ).fetchall()
                already_linked = any(
                    _json_details(item).get("flow_id") == flow["flow_id"]
                    and _json_details(item).get("scheduled_for")
                    == scheduled_for
                    for item in linked_events
                )
            if existing.get("dispatch_ready"):
                if not already_linked:
                    raise ConflictError("已授权定时流缺少对应周期审计")
                return existing
            current_config_sha256 = self._config_sha256(
                name=str(current["name"]),
                workflow_name=str(current["workflow_name"]),
                draft_id=str(current["draft_id"]),
                goal_text=str(current["goal_text"]),
                schedule_kind=str(current["schedule_kind"]),
                schedule=json.loads(current["schedule_json"]),
                enabled=bool(current["enabled"]),
                client_request_id=current["client_request_id"],
            )
            if (
                current["deleted_at"] is not None
                or current["pending_run_at"] != scheduled_for
                or current_config_sha256 != launch_config_sha256
            ):
                raise ConflictError(
                    "定时任务周期或配置在启动期间已经变化"
                )
            current_revision = int(current["revision"])
            changed = db.execute(
                """
                UPDATE agent_jobs
                SET last_flow_id = ?, last_error = NULL,
                    pending_run_at = NULL,
                    revision = revision + 1, updated_at = ?
                WHERE job_id = ? AND deleted_at IS NULL
                  AND pending_run_at = ?
                  AND revision = ?
                """,
                (
                    flow["flow_id"],
                    now,
                    job["job_id"],
                    scheduled_for,
                    current_revision,
                ),
            )
            if changed.rowcount != 1:
                raise ConflictError("定时任务周期已变化，拒绝记录重复执行")
            self.flow_runtime.authorize_dispatch_in_transaction(
                db,
                flow["flow_id"],
                actor_id="system",
            )
            self._append_event(
                db,
                job_id=job["job_id"],
                event_type="job_flow_created",
                actor_id="system",
                details={
                    "flow_id": flow["flow_id"],
                    "trigger_type": "schedule",
                    "scheduled_for": scheduled_for,
                    "launch_revision": launch_revision,
                    "commit_revision": current_revision,
                    "launch_config_sha256": launch_config_sha256,
                },
                occurred_at=now,
            )
        with suppress(ConflictError):
            self.flow_runtime.schedule_existing(flow["flow_id"])
        return self.flow_runtime.store.get(flow["flow_id"])

    def _record_job_error(
        self,
        job_id: str,
        error_code: str,
        *,
        scheduled_for: str | None = None,
    ) -> None:
        now = utc_text()
        safe_code = redact_text(error_code, maximum=128)
        with self.repository._transaction() as db:
            row = db.execute(
                "SELECT * FROM agent_jobs WHERE job_id = ?",
                (job_id,),
            ).fetchone()
            if row is None:
                return
            if not self._verify_row_in_transaction(db, row)["valid"]:
                return
            if (
                scheduled_for is not None
                and row["pending_run_at"] != scheduled_for
            ):
                # Another process already completed or superseded this exact
                # occurrence.  Its successful state must not be overwritten
                # with the losing worker's benign CAS conflict.
                return
            changed = db.execute(
                """
                UPDATE agent_jobs
                SET last_error = ?,
                    pending_run_at = CASE
                        WHEN ? IS NOT NULL AND pending_run_at = ?
                        THEN NULL ELSE pending_run_at END,
                    revision = revision + 1, updated_at = ?
                WHERE job_id = ?
                  AND (? IS NULL OR pending_run_at = ?)
                """,
                (
                    safe_code,
                    scheduled_for,
                    scheduled_for,
                    now,
                    job_id,
                    scheduled_for,
                    scheduled_for,
                ),
            )
            if changed.rowcount != 1:
                return
            self._append_event(
                db,
                job_id=job_id,
                event_type="job_launch_failed",
                actor_id="system",
                details={
                    "error_code": safe_code,
                    "scheduled_for": scheduled_for,
                    "occurrence_closed": scheduled_for is not None,
                },
                occurred_at=now,
            )

    def _recover_next_runs(self) -> None:
        now = utc_now()
        with self.repository._transaction() as db:
            rows = db.execute(
                """
                SELECT * FROM agent_jobs
                WHERE enabled = 1 AND deleted_at IS NULL
                  AND schedule_kind IN ('daily', 'interval')
                  AND next_run_at IS NULL
                """
            ).fetchall()
            for row in rows:
                if not self._verify_row_in_transaction(db, row)["valid"]:
                    continue
                schedule = json.loads(row["schedule_json"])
                next_run = _next_run_at(
                    str(row["schedule_kind"]),
                    schedule,
                    after=now,
                )
                timestamp = utc_text(now)
                db.execute(
                    """
                    UPDATE agent_jobs
                    SET next_run_at = ?, revision = revision + 1,
                        updated_at = ?
                    WHERE job_id = ?
                    """,
                    (next_run, timestamp, row["job_id"]),
                )
                self._append_event(
                    db,
                    job_id=str(row["job_id"]),
                    event_type="job_schedule_recovered",
                    actor_id="system",
                    details={"next_run_at": next_run},
                    occurred_at=timestamp,
                )

    def _workflow(self, value: Any) -> str:
        if value not in _WORKFLOWS:
            raise ValueError("workflow_name 不受支持")
        return str(value)

    def _draft_id(self, value: Any) -> str:
        draft_id = _safe_identifier(value, "draft_id")
        self.repository.get_draft(draft_id)
        return draft_id

    @staticmethod
    def _append_event(
        db: Any,
        *,
        job_id: str,
        event_type: str,
        actor_id: str,
        details: dict[str, Any],
        occurred_at: str,
    ) -> None:
        row = db.execute(
            """
            SELECT * FROM agent_jobs
            WHERE job_id = ?
            """,
            (job_id,),
        ).fetchone()
        if row is None:
            raise NotFoundError("定时任务不存在")
        sequence = int(row["event_count"]) + 1
        previous_hash = str(row["event_head_hash"] or _ZERO_HASH)
        safe_details = {
            **sanitize(details),
            "job_state_sha256": AgentJobScheduler._state_sha256(row),
        }
        event = {
            "job_id": job_id,
            "sequence": sequence,
            "event_type": event_type,
            "actor_id": actor_id,
            "details": safe_details,
            "occurred_at": occurred_at,
            "previous_hash": previous_hash,
        }
        event_hash = sha256_json(event)
        db.execute(
            """
            INSERT INTO agent_job_events (
                job_id, sequence, event_type, actor_id, details_json,
                occurred_at, previous_hash, event_hash
            ) VALUES (?, ?, ?, ?, ?, ?, ?, ?)
            """,
            (
                job_id,
                sequence,
                event_type,
                actor_id,
                canonical_json(safe_details),
                occurred_at,
                previous_hash,
                event_hash,
            ),
        )
        changed = db.execute(
            """
            UPDATE agent_jobs
            SET event_count = ?, event_head_hash = ?
            WHERE job_id = ? AND event_count = ?
              AND event_head_hash = ?
            """,
            (
                sequence,
                event_hash,
                job_id,
                sequence - 1,
                previous_hash,
            ),
        )
        if changed.rowcount != 1:
            raise ConflictError("定时任务审计锚点冲突")

    @classmethod
    def _verify_row_in_transaction(
        cls,
        db: Any,
        row: Any,
    ) -> dict[str, Any]:
        event_rows = db.execute(
            """
            SELECT * FROM agent_job_events
            WHERE job_id = ?
            ORDER BY sequence
            """,
            (row["job_id"],),
        ).fetchall()
        try:
            events = [cls._event_row(event) for event in event_rows]
            return cls._verify_events(row, events)
        except (json.JSONDecodeError, TypeError, ValueError):
            return {
                "valid": False,
                "event_count": len(event_rows),
                "head_hash": str(row["event_head_hash"]),
                "config_bound": False,
                "state_bound": False,
            }

    @staticmethod
    def _config_sha256(
        *,
        name: str,
        workflow_name: str,
        draft_id: str,
        goal_text: str,
        schedule_kind: str,
        schedule: dict[str, Any],
        enabled: bool,
        client_request_id: str | None,
    ) -> str:
        return sha256_json(
            {
                "name": name,
                "workflow_name": workflow_name,
                "draft_id": draft_id,
                "goal_text": goal_text,
                "schedule_kind": schedule_kind,
                "schedule": schedule,
                "enabled": enabled,
                "client_request_id": client_request_id,
            }
        )

    @staticmethod
    def _state_sha256(row: Any) -> str:
        return sha256_json(
            {
                "job_id": str(row["job_id"]),
                "actor_id": str(row["actor_id"]),
                "client_request_id": row["client_request_id"],
                "name": str(row["name"]),
                "workflow_name": str(row["workflow_name"]),
                "draft_id": row["draft_id"],
                "goal_text": str(row["goal_text"]),
                "schedule_kind": str(row["schedule_kind"]),
                "schedule": json.loads(row["schedule_json"]),
                "enabled": bool(row["enabled"]),
                "next_run_at": row["next_run_at"],
                "pending_run_at": row["pending_run_at"],
                "last_run_at": row["last_run_at"],
                "last_flow_id": row["last_flow_id"],
                "last_error": row["last_error"],
                "revision": int(row["revision"]),
                "created_at": str(row["created_at"]),
                "updated_at": str(row["updated_at"]),
                "deleted_at": row["deleted_at"],
            }
        )

    @staticmethod
    def _row(row: Any) -> dict[str, Any]:
        return {
            "job_id": str(row["job_id"]),
            "actor_id": str(row["actor_id"]),
            "name": str(row["name"]),
            "workflow_name": str(row["workflow_name"]),
            "draft_id": row["draft_id"],
            "goal_text": str(row["goal_text"]),
            "schedule_kind": str(row["schedule_kind"]),
            "schedule": json.loads(row["schedule_json"]),
            "enabled": bool(row["enabled"]),
            "next_run_at": row["next_run_at"],
            "pending_run_at": row["pending_run_at"],
            "last_run_at": row["last_run_at"],
            "last_flow_id": row["last_flow_id"],
            "last_error": row["last_error"],
            "revision": int(row["revision"]),
            "created_at": str(row["created_at"]),
            "updated_at": str(row["updated_at"]),
            "deleted_at": row["deleted_at"],
        }

    @staticmethod
    def _event_row(row: Any) -> dict[str, Any]:
        return {
            "job_id": str(row["job_id"]),
            "sequence": int(row["sequence"]),
            "event_type": str(row["event_type"]),
            "actor_id": str(row["actor_id"]),
            "details": json.loads(row["details_json"]),
            "occurred_at": str(row["occurred_at"]),
            "previous_hash": str(row["previous_hash"]),
            "event_hash": str(row["event_hash"]),
        }

    @staticmethod
    def _verify_events(
        job_row: Any,
        events: list[dict[str, Any]],
    ) -> dict[str, Any]:
        previous_hash = _ZERO_HASH
        valid = len(events) == int(job_row["event_count"])
        for expected, event in enumerate(events, 1):
            material = {
                key: event[key]
                for key in (
                    "job_id",
                    "sequence",
                    "event_type",
                    "actor_id",
                    "details",
                    "occurred_at",
                    "previous_hash",
                )
            }
            if (
                event["sequence"] != expected
                or event["previous_hash"] != previous_hash
                or sha256_json(material) != event["event_hash"]
            ):
                valid = False
                break
            previous_hash = event["event_hash"]
        if previous_hash != str(job_row["event_head_hash"]):
            valid = False
        config_event = next(
            (
                event
                for event in reversed(events)
                if event["event_type"]
                in {"job_created", "job_updated", "job_deleted"}
            ),
            None,
        )
        expected_config_hash = (
            config_event["details"].get("config_sha256")
            or config_event["details"].get("request_sha256")
            if config_event is not None
            else None
        )
        actual_config_hash = AgentJobScheduler._config_sha256(
            name=str(job_row["name"]),
            workflow_name=str(job_row["workflow_name"]),
            draft_id=str(job_row["draft_id"]),
            goal_text=str(job_row["goal_text"]),
            schedule_kind=str(job_row["schedule_kind"]),
            schedule=json.loads(job_row["schedule_json"]),
            enabled=bool(job_row["enabled"]),
            client_request_id=job_row["client_request_id"],
        )
        config_bound = expected_config_hash is not None
        if (
            not config_bound
            or expected_config_hash != actual_config_hash
            or not events
            or events[0]["event_type"] != "job_created"
            or events[0]["actor_id"] != str(job_row["actor_id"])
        ):
            valid = False
        expected_state_hash = (
            events[-1]["details"].get("job_state_sha256")
            if events
            and isinstance(events[-1].get("details"), dict)
            else None
        )
        state_bound = expected_state_hash is not None
        if (
            not state_bound
            or expected_state_hash
            != AgentJobScheduler._state_sha256(job_row)
        ):
            valid = False
        return {
            "valid": valid,
            "event_count": int(job_row["event_count"]),
            "head_hash": str(job_row["event_head_hash"]),
            "config_bound": config_bound,
            "state_bound": state_bound,
        }

    @staticmethod
    def _trigger_progress(value: Any) -> dict[str, Any]:
        if not isinstance(value, dict):
            raise ConflictError("业务事件触发进度结构损坏")
        matched = value.get("matched_job_ids", [])
        succeeded = value.get("succeeded", [])
        failed = value.get("failed", [])
        completed = value.get("completed", False)
        if (
            not isinstance(matched, list)
            or any(not isinstance(item, str) for item in matched)
            or len(matched) != len(set(matched))
            or not isinstance(succeeded, list)
            or not isinstance(failed, list)
            or not isinstance(completed, bool)
        ):
            raise ConflictError("业务事件触发进度结构损坏")
        return {
            "matched_job_ids": matched,
            "succeeded": succeeded,
            "failed": failed,
            "completed": completed,
        }

    @staticmethod
    def _trigger_record_sha256(
        *,
        event_id: str,
        actor_id: str,
        client_event_id: str,
        event_type: str,
        draft_id: str | None,
        payload_sha256: str,
        matched_job_ids: list[str],
        occurred_at: str,
    ) -> str:
        return sha256_json(
            {
                "event_id": event_id,
                "actor_id": actor_id,
                "client_event_id": client_event_id,
                "event_type": event_type,
                "draft_id": draft_id,
                "payload_sha256": payload_sha256,
                "matched_job_ids": matched_job_ids,
                "occurred_at": occurred_at,
            }
        )

    @staticmethod
    def _trigger_progress_sha256(
        *,
        event_id: str,
        record_sha256: str,
        revision: int,
        progress: dict[str, Any],
    ) -> str:
        return sha256_json(
            {
                "event_id": event_id,
                "record_sha256": record_sha256,
                "revision": revision,
                "progress": progress,
            }
        )

    @classmethod
    def _verify_trigger_row(cls, row: Any) -> dict[str, Any]:
        try:
            payload = json.loads(row["payload_json"])
            matched = json.loads(row["matched_jobs_json"])
            progress = cls._trigger_progress(
                json.loads(row["triggered_jobs_json"])
            )
            revision = int(row["progress_revision"])
            if (
                not isinstance(payload, dict)
                or not isinstance(matched, list)
                or any(not isinstance(item, str) for item in matched)
                or len(matched) != len(set(matched))
                or revision < 1
                or progress["matched_job_ids"] != matched
            ):
                raise ValueError("invalid trigger record")
            payload_hash = sha256_json(payload)
            expected_record_hash = cls._trigger_record_sha256(
                event_id=str(row["event_id"]),
                actor_id=str(row["actor_id"]),
                client_event_id=str(row["client_event_id"]),
                event_type=str(row["event_type"]),
                draft_id=row["draft_id"],
                payload_sha256=payload_hash,
                matched_job_ids=matched,
                occurred_at=str(row["occurred_at"]),
            )
            expected_progress_hash = cls._trigger_progress_sha256(
                event_id=str(row["event_id"]),
                record_sha256=expected_record_hash,
                revision=revision,
                progress=progress,
            )
            result_job_ids = [
                item.get("job_id")
                for collection in (
                    progress["succeeded"],
                    progress["failed"],
                )
                for item in collection
                if isinstance(item, dict)
            ]
            if (
                str(row["payload_sha256"]) != payload_hash
                or row["record_sha256"] != expected_record_hash
                or row["progress_sha256"] != expected_progress_hash
                or len(result_job_ids) != len(set(result_job_ids))
                or any(job_id not in matched for job_id in result_job_ids)
            ):
                raise ValueError("trigger integrity mismatch")
        except (
            AttributeError,
            json.JSONDecodeError,
            TypeError,
            ValueError,
        ):
            return {
                "valid": False,
                "payload": {},
                "matched_job_ids": [],
                "progress": {
                    "matched_job_ids": [],
                    "succeeded": [],
                    "failed": [],
                    "completed": False,
                },
                "revision": 0,
                "record_sha256": None,
                "progress_sha256": None,
            }
        return {
            "valid": True,
            "payload": payload,
            "matched_job_ids": matched,
            "progress": progress,
            "revision": revision,
            "record_sha256": expected_record_hash,
            "progress_sha256": expected_progress_hash,
        }

    def _claim_trigger_in_transaction(
        self,
        db: Any,
        *,
        event_id: str,
        owner_id: str,
    ) -> bool:
        now = utc_text()
        lease_expires_at = utc_text(
            utc_now() + timedelta(seconds=_EVENT_CLAIM_SECONDS)
        )
        claim = db.execute(
            """
            SELECT * FROM agent_trigger_claims WHERE event_id = ?
            """,
            (event_id,),
        ).fetchone()
        if claim is None:
            db.execute(
                """
                INSERT INTO agent_trigger_claims (
                    event_id, owner_id, lease_expires_at, updated_at
                ) VALUES (?, ?, ?, ?)
                """,
                (event_id, owner_id, lease_expires_at, now),
            )
            return True
        if (
            str(claim["owner_id"]) != owner_id
            and str(claim["lease_expires_at"]) > now
        ):
            return False
        changed = db.execute(
            """
            UPDATE agent_trigger_claims
            SET owner_id = ?, lease_expires_at = ?, updated_at = ?
            WHERE event_id = ? AND (
                owner_id = ? OR lease_expires_at <= ?
            )
            """,
            (
                owner_id,
                lease_expires_at,
                now,
                event_id,
                owner_id,
                now,
            ),
        )
        return changed.rowcount == 1

    def _renew_trigger_claim(self, event_id: str, *, owner_id: str) -> None:
        now = utc_text()
        lease_expires_at = utc_text(
            utc_now() + timedelta(seconds=_EVENT_CLAIM_SECONDS)
        )
        with self.repository._transaction() as db:
            changed = db.execute(
                """
                UPDATE agent_trigger_claims
                SET lease_expires_at = ?, updated_at = ?
                WHERE event_id = ? AND owner_id = ?
                """,
                (
                    lease_expires_at,
                    now,
                    event_id,
                    owner_id,
                ),
            )
            if changed.rowcount != 1:
                raise ConflictError(
                    "业务事件处理租约已经转移，请稍后读取最终状态"
                )

    def _assert_trigger_claim_in_transaction(
        self,
        db: Any,
        *,
        event_id: str,
        owner_id: str,
    ) -> None:
        claim = db.execute(
            """
            SELECT owner_id, lease_expires_at
            FROM agent_trigger_claims WHERE event_id = ?
            """,
            (event_id,),
        ).fetchone()
        if (
            claim is None
            or str(claim["owner_id"]) != owner_id
            or str(claim["lease_expires_at"]) <= utc_text()
        ):
            raise ConflictError("业务事件处理租约已经转移")

    def _release_trigger_claim(self, event_id: str, *, owner_id: str) -> None:
        with self.repository._transaction() as db:
            db.execute(
                """
                DELETE FROM agent_trigger_claims
                WHERE event_id = ? AND owner_id = ?
                """,
                (event_id, owner_id),
            )

    @classmethod
    def _merge_trigger_progress(
        cls,
        current: dict[str, Any],
        incoming: dict[str, Any],
    ) -> dict[str, Any]:
        left = cls._trigger_progress(current)
        right = cls._trigger_progress(incoming)
        if left["matched_job_ids"] != right["matched_job_ids"]:
            raise ConflictError("业务事件匹配任务集合发生变化")
        matched = left["matched_job_ids"]

        def indexed(
            collection: list[Any],
            *,
            outcome: str,
        ) -> dict[str, dict[str, Any]]:
            result: dict[str, dict[str, Any]] = {}
            for item in collection:
                if not isinstance(item, dict):
                    raise ConflictError("业务事件触发结果结构损坏")
                job_id = item.get("job_id")
                if not isinstance(job_id, str) or job_id not in matched:
                    raise ConflictError("业务事件触发结果包含未知任务")
                previous = result.get(job_id)
                if previous is not None and previous != item:
                    raise ConflictError(
                        f"业务事件任务 {job_id} 存在冲突的{outcome}结果"
                    )
                result[job_id] = dict(item)
            return result

        left_success = indexed(left["succeeded"], outcome="成功")
        right_success = indexed(right["succeeded"], outcome="成功")
        for job_id in set(left_success).intersection(right_success):
            if left_success[job_id] != right_success[job_id]:
                raise ConflictError(
                    f"业务事件任务 {job_id} 关联了不同的智能体流"
                )
        successes = {**left_success, **right_success}
        failures = {
            **indexed(left["failed"], outcome="失败"),
            **indexed(right["failed"], outcome="失败"),
        }
        for job_id in successes:
            failures.pop(job_id, None)
        return {
            "matched_job_ids": list(matched),
            "succeeded": [
                successes[job_id] for job_id in matched if job_id in successes
            ],
            "failed": [
                failures[job_id] for job_id in matched if job_id in failures
            ],
            "completed": bool(left["completed"] or right["completed"]),
        }

    def _persist_trigger_progress(
        self,
        *,
        event_id: str,
        record_sha256: str,
        expected_revision: int,
        expected_progress_sha256: str,
        progress: dict[str, Any],
        claim_owner: str,
    ) -> tuple[int, str, dict[str, Any]]:
        desired = self._trigger_progress(progress)
        revision = expected_revision
        progress_hash = expected_progress_sha256
        for _attempt in range(16):
            next_revision = revision + 1
            next_hash = self._trigger_progress_sha256(
                event_id=event_id,
                record_sha256=record_sha256,
                revision=next_revision,
                progress=desired,
            )
            with self.repository._transaction() as db:
                self._assert_trigger_claim_in_transaction(
                    db,
                    event_id=event_id,
                    owner_id=claim_owner,
                )
                changed = db.execute(
                    """
                    UPDATE agent_trigger_events
                    SET triggered_jobs_json = ?, progress_revision = ?,
                        progress_sha256 = ?
                    WHERE event_id = ? AND record_sha256 = ?
                      AND progress_revision = ? AND progress_sha256 = ?
                    """,
                    (
                        canonical_json(desired),
                        next_revision,
                        next_hash,
                        event_id,
                        record_sha256,
                        revision,
                        progress_hash,
                    ),
                )
                if changed.rowcount == 1:
                    return next_revision, next_hash, desired
                row = db.execute(
                    """
                    SELECT * FROM agent_trigger_events
                    WHERE event_id = ?
                    """,
                    (event_id,),
                ).fetchone()
                if row is None:
                    raise ConflictError("业务事件记录在更新期间消失")
                verified = self._verify_trigger_row(row)
                if (
                    not verified["valid"]
                    or verified["record_sha256"] != record_sha256
                ):
                    raise ConflictError(
                        "业务事件记录完整性校验失败，拒绝合并进度"
                    )
                merged = self._merge_trigger_progress(
                    verified["progress"],
                    desired,
                )
                if merged == verified["progress"]:
                    return (
                        int(verified["revision"]),
                        str(verified["progress_sha256"]),
                        merged,
                    )
                desired = merged
                revision = int(verified["revision"])
                progress_hash = str(verified["progress_sha256"])
        raise ConflictError("业务事件触发进度并发更新过多，请重试")

    @classmethod
    def _trigger_row(cls, row: Any, *, replayed: bool) -> dict[str, Any]:
        verification = cls._verify_trigger_row(row)
        return {
            "event_id": str(row["event_id"]),
            "actor_id": str(row["actor_id"]),
            "client_event_id": str(row["client_event_id"]),
            "event_type": str(row["event_type"]),
            "draft_id": row["draft_id"],
            "payload": verification["payload"],
            "payload_sha256": str(row["payload_sha256"]),
            "triggered": verification["progress"],
            "occurred_at": str(row["occurred_at"]),
            "replayed": replayed,
            "integrity": {
                "valid": verification["valid"],
                "record_sha256": verification["record_sha256"],
                "progress_revision": verification["revision"],
                "progress_sha256": verification["progress_sha256"],
            },
        }


__all__ = ["AgentJobScheduler"]
